query:
insert into public.profiles (name, professional_title, location, email, linkedin_url, phone, bio, photo_path, photo_alt) values ('Mohammed Bajhaw', 'Mechatronics Engineering Researcher · Autonomous Systems & Robotics', 'Elazığ, Türkiye', 'mohammedbajhaw2020@gmail.com', 'https://linkedin.com/in/mohammedbajhaw', '+905359324792', 'Mechatronics researcher and engineer focused on autonomous systems, robotics, and embedded platforms. I integrate advanced sensing, SLAM, and AI to build dependable robotic systems for real-world environments.', null, null);
insert into public.education (institution, degree, field, location, start_year, end_year, description, sort_order) values ('Fırat University', 'Bachelor’s Degree', 'Mechatronics Engineering', 'Elazığ, Türkiye', '2021', '2026', 'Mechatronics Engineering studies with an academic and project-based focus on robotics, autonomous systems, embedded computing, and intelligent machines.', 1);
insert into public.publications (title, venue, publication_date, status, authors, summary, details, keywords, url, sort_order) values ('Drift-Resilient Indoor 3D Mapping in GPS-Denied Environments Using RKO-LIO with Velodyne–Pixhawk Integration in ROS 2', 'ICHORA 2026 · IEEE Conference', 'May 2026', 'Accepted & Published', 'Co-author', 'A robust indoor localization and three-dimensional mapping approach for GPS-denied environments using ROS 2, Velodyne LiDAR, and Pixhawk integration.', 'This research presents a multi-sensor pipeline for localization and mapping in indoor environments. The full methodology, experiments, and references can be maintained from the administration page and replaced with the approved paper text.', array['LiDAR SLAM', 'ROS 2', 'GPS-Denied', 'Autonomous UAV'], null, 1), ('Demonstrating the Efficiency of RKO-LIO on a DJI UAV Platform Utilizing Drone Built-in IMU for GPS-Denied Mapping', 'Research Paper', '2026', 'Research Paper', 'First author', 'A hardware-software integration framework for GPS-denied UAVs using onboard IMU data and LiDAR SLAM algorithms.', 'This work evaluates RKO-LIO on a DJI UAV platform and investigates how the built-in IMU can improve the reliability of three-dimensional mapping where GPS signals are unavailable.', array['RKO-LIO', 'DJI UAV', 'Built-in IMU', '3D Mapping'], null, 2);
insert into public.experiences (role, organization, location, start_date, end_date, is_current, summary, highlights, sort_order) values ('Volunteer Researcher', 'RAI Laboratory, Fırat University', 'Elazığ, Türkiye', 'Sep 2025', 'Present', true, 'Research and development for autonomous disaster management using heterogeneous robotic systems within the TÜBİTAK 1001 project.', array['Tested SLAM algorithms in GPS-denied environments and supported UAV navigation and control operations.', 'Collected field data and supported three-dimensional CAD fixture design for sensor integration.', 'Contributed technical work to academic research preparation and publication.'], 1), ('Robotics Research Intern', 'RAI Laboratory, Fırat University', 'Elazığ, Türkiye', 'Jul 2025', 'Sep 2025', false, 'Supported hardware-software integration of the DJI Matrice 350 RTK with NVIDIA Jetson Orin NX.', array['Conducted simulation and field tests for SLAM workflows using Velodyne LiDAR and Intel RealSense cameras.', 'Supported sensor integration and edge-computing deployment for aerial robotic platforms.'], 2);
